        intro = card_txt.replace(' kartınız', ' kartınıza') + ' ait ' + sdate(sd) + ' tarihinde kesilen ekstre '
        if not name:
            intro = 'Sonu ' + l4w + ' ile biten kartınıza ait ' + sdate(sd) + ' tarihinde kesilen ekstre '
