                Y = amount(blk.get('remainingDebt'), 'TL')
                T = amount(blk.get('remainingMinPayment'), 'TL')
                rm = num(blk.get('remainingMinPayment'))
                mp = num(blk.get('minPayment'))
                if rm <= 0:
                    s = suf('Türk Lirası borcunuz ' + X + ', kalan toplam borcunuz ' + Y) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                elif rm >= mp:
                    s = suf('Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z) + '.'
                else:
                    s = suf('Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + ', kalan toplam borcunuz ' + Y + ', kalan minimum ödeme tutarınız ' + T) + '.'
            else:
                nm = CUR[c][0]
                s = suf(nm + ' borcunuz ' + amount(blk.get('statementDebt'), c) + ', kalan toplam borcunuz ' + amount(blk.get('remainingDebt'), c) + ', ödenmesi gereken minimum tutar ' + amount(blk.get('minPayment'), c)) + '.'
            parts.append(pre + s)
        if clear:
            parts.append(join_tr([CUR[c][0] for c in clear]) + ' borcunuz bulunmamaktadır.')
        if lp is not None:
            if td is not None and lp == td:
                parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
            else:
                parts.append(suf('Borçlarınız için son ödeme tarihiniz ' + sdate(lp)) + '.')
    vars['reading_text'] = ' '.join(p for p in parts if p)
    if int(str(vars.get('elig_count') or '1')) > 1:
        vars['menu_stage'] = 'another_card'
        q = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
    else:
        vars['menu_stage'] = 'offer'
        q = offer_line()
        if not q:
            vars['menu_stage'] = 'nothing'
            q = 'Başka bir isteğiniz var mı?'
    vars['speak_text'] = vars['reading_text'] + ' ' + q
    vars['menu_intent'] = ''
except Exception:
    vars['reading_text'] = ''
    vars['speak_text'] = 'Şu anda borç bilgilerinizi okuyamıyorum.'
    vars['menu_stage'] = 'offer'

